#!/usr/bin/env node
/**
 * Extracts the Migration entries from src-tauri/src/lib.rs into a static module
 * used only by the browser mock. Run with:
 *
 *   node scripts/extract-migrations.mjs
 *
 * The generated file is committed so the browser build never parses Rust at
 * runtime and needs no Tauri/Rust toolchain.
 */
import { mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname } from "node:path";
import { fileURLToPath } from "node:url";

const root = fileURLToPath(new URL("..", import.meta.url));
const sourcePath = `${root}src-tauri/src/lib.rs`;
const outputPath = `${root}src/lib/browser/migrations.generated.ts`;

const source = readFileSync(sourcePath, "utf8");

/** Decodes the escape sequences allowed in a normal Rust string literal. */
function unescapeRustString(value) {
  let result = "";
  for (let index = 0; index < value.length; index += 1) {
    const character = value[index];
    if (character !== "\\") {
      result += character;
      continue;
    }
    const next = value[index + 1];
    index += 1;
    switch (next) {
      case "n":
        result += "\n";
        break;
      case "r":
        result += "\r";
        break;
      case "t":
        result += "\t";
        break;
      case "0":
        result += "\0";
        break;
      case "\\":
        result += "\\";
        break;
      case '"':
        result += '"';
        break;
      case "'":
        result += "'";
        break;
      case "\n":
        // Rust line continuation: drop the newline and following indentation.
        while (value[index + 1] === " " || value[index + 1] === "\t") index += 1;
        break;
      case "u":
        if (value[index + 1] !== "{") throw new Error("Unsupported \\u escape");
        {
          const end = value.indexOf("}", index + 2);
          if (end < 0) throw new Error("Unterminated \\u escape");
          result += String.fromCodePoint(
            Number.parseInt(value.slice(index + 2, end), 16),
          );
          index = end;
        }
        break;
      default:
        result += next ?? "";
    }
  }
  return result;
}

const migrations = [];
const pattern =
  /version:\s*(\d+),\s*description:\s*"((?:[^"\\]|\\.)*)",[\s\S]*?sql:\s*"((?:[^"\\]|\\.)*)"/g;

for (const match of source.matchAll(pattern)) {
  const version = Number(match[1]);
  const description = unescapeRustString(match[2]);
  const sql = unescapeRustString(match[3]);
  const name = `${String(version).padStart(3, "0")}_${description}`;
  migrations.push({ version, name, sql });
}

if (migrations.length === 0) {
  throw new Error(`No migrations found in ${sourcePath}`);
}

migrations.sort((a, b) => a.version - b.version);
const seen = new Set();
for (const migration of migrations) {
  if (seen.has(migration.version)) {
    throw new Error(`Duplicate migration version ${migration.version}`);
  }
  seen.add(migration.version);
}

const body = migrations
  .map(
    (migration) =>
      `  {\n    name: ${JSON.stringify(migration.name)},\n    sql: ${JSON.stringify(migration.sql)},\n  },`,
  )
  .join("\n");

const output = `// Generated by scripts/extract-migrations.mjs — do not edit by hand.
// Source: src-tauri/src/lib.rs (${migrations.length} migrations).
import type { BrowserMigration } from "./migrations";

export const GENERATED_MIGRATIONS: BrowserMigration[] = [
${body}
];
`;

mkdirSync(dirname(outputPath), { recursive: true });
writeFileSync(outputPath, output, "utf8");
console.log(
  `Extracted ${migrations.length} migrations into src/lib/browser/migrations.generated.ts`,
);
